async function checkout() {
  if (cart.length === 0) { 
    alert('Cart empty'); 
    return; 
  }

  // FIXED: map correct fields
  const order = { 
    items: cart.map(i => ({
      productId: i.id,      // product ID
      quantity: i.qty       // the amount user added
    }))
  };

  try {
    const res = await placeOrder(order);
    alert('Order placed successfully. Total: $' + res.total);
    onOrderPlaced();
  } catch (err) {
    alert('Order failed: ' + err.message);
  }
}
